"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFeatureContent } from "./components/feature-sections/content";
import View2 from "./components/feature-sections/variants/03-product-hotspots";
const variants = {"product-hotspots":View2};
export type { ArtemisFeatureContent, ArtemisFeatureImage, ArtemisFeatureItem, ArtemisFeatureLink } from "./components/feature-sections/content";
export interface ArtemisFeatureSectionsProps { className?: string; variant?: "product-hotspots"; /** The words on the feature section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFeatureContent>; }
export function ArtemisFeatureSections({ className, variant = "product-hotspots", content }: ArtemisFeatureSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisFeatureLink {
  label: string;
  href: string;
}

/** A picture shown as content, and the words that stand in for it. */
export interface ArtemisFeatureImage {
  src: string;
  alt: string;
}

/** One feature: a row, card, step or tab, depending on the layout. */
export interface ArtemisFeatureItem {
  /** The feature's name. All layouts; signal-grid puts its first word on a line of its own. */
  title: string;
  /** A sentence or two about the feature. All layouts; product-hotspots, steps, tabs and stage-tabs show it for the chosen feature only. */
  description: string;
  /** A short name: the tab in tabs and stage-tabs (which show the title when you leave this out), and the words after the number in alternating-rows. */
  label?: string;
  /** Short points under the description. alternating-rows, product-hotspots and tabs. */
  bullets?: string[];
  /** A figure shown large. voice-ai (first card) and control-deck (third and fourth cards; on the third, a trailing % is set small and fills the bar). */
  stat?: string;
  /** The feature's icon. visual-benefits, signal-grid, voice-ai (first card), control-deck (fourth and fifth cards) and tabs, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
  /** A product picture. tabs, which shows its own picture for that slot when you leave this out. */
  image?: ArtemisFeatureImage;
}

/**
 * The words on an Artemis feature section. Every layout reads this shape, so you can switch layouts and keep them.
 * An empty `badge`, `headlineAccent` or `subhead` leaves that line out.
 */
export interface ArtemisFeatureContent {
  /** A short line above the headline. All layouts except visual-benefits, alternating-rows and stage-tabs. */
  badge?: string;
  /** The section heading. All layouts except stage-tabs. */
  headline?: string;
  /**
   * The second part of the heading. showcase, signal-grid, control-deck, voice-ai, list, bento and tabs put it on a
   * line of its own, steps sets it in the accent color, and the other layouts with a heading run it on after the
   * headline. It goes with `headline`: give a headline without it and the heading has no second part.
   */
  headlineAccent?: string;
  /** A sentence or two under the heading. All layouts except visual-benefits, tabs and stage-tabs. */
  subhead?: string;
  /**
   * The features. All layouts. Today's counts look best: three in visual-benefits, alternating-rows, showcase,
   * benefits-triptych and steps; four in product-hotspots, voice-ai, list, tabs and stage-tabs; five in control-deck
   * (which shows no more than five) and bento; six in signal-grid.
   */
  items: ArtemisFeatureItem[];
  /** The button under the features. visual-benefits. */
  cta?: ArtemisFeatureLink;
}

"use client";
// @zeus-internal
import { useId as useArtemisInstanceId } from "react";
import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { useEffect, useState } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { WorkspaceArt } from "./03-product-hotspots/workspace-art";
import type { ArtemisFeatureContent, ArtemisFeatureItem } from "../content";
const DEFAULT = {
    badge: "A closer look",
    headline: "Get to know your next workspace.",
    subhead: "A place for the plan, the people, and the little details. Pick a marker to take a closer look.",
    items: [
        {
            title: "A home for every project",
            description: "Keep your team\u2019s work organized in shared spaces. Everything stays easy to find, from the first brief to the final handoff.",
            bullets: ["Group related work", "Give each team its own space"],
        },
        {
            title: "See work your way",
            description: "Switch perspectives without rebuilding your workflow. Bring the right view to planning, progress reviews, and everyday work.",
            bullets: ["Board, list, and timeline views", "One source of truth"],
        },
        {
            title: "Turn plans into progress",
            description: "Move from a promising idea to a finished task. Owners, deadlines, and context travel with the work.",
            bullets: ["Clear ownership and due dates", "Keep the conversation in context"],
        },
        {
            title: "Stay in the loop",
            description: "Bring the right people into the picture. Share progress and collaborate without another status meeting.",
            bullets: ["Invite teammates and guests", "Keep everyone on the same page"],
        },
    ],
} satisfies ArtemisFeatureContent;
/** Where each slot's marker sits on the workspace art. */
const SPOTS = [
    { left: "18%", top: "56%" },
    { left: "60%", top: "25%" },
    { left: "48%", top: "60%" },
    { left: "87%", top: "14%" },
];

const pad = (n: number) => String(n).padStart(2, "0");
const MARKER_BASE = "art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:hover:bg-transparent art:hover:text-inherit art:absolute art:z-10 art:hidden art:size-8 art:-translate-x-1/2 art:-translate-y-1/2 art:items-center art:justify-center art:border art:text-xs art:font-medium art:transition-colors art:before:absolute art:before:-inset-1 art:before:rounded-full art:before:content-[''] art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring art:@min-[640px]/artemis:flex";
const MARKER_ON = "art:border-transparent art:text-primary-foreground art:rounded-full";
const MARKER_OFF = "art:border-border art:bg-background art:text-foreground art:hover:border-foreground/40 art:rounded-full";
const ROW_HEAD = "art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:font-normal art:hover:bg-transparent";
const ROW_TAIL = "art:flex art:min-h-12 art:w-full art:items-center art:gap-3 art:border art:px-3 art:py-2 art:text-left art:text-sm art:transition-colors art:focus-visible:outline-2 art:focus-visible:outline-ring";
const ROW_ON = `${ROW_HEAD} art:hover:text-inherit ${ROW_TAIL} art:border-border art:text-foreground art:rounded-full`;
const ROW_OFF = `${ROW_HEAD} ${ROW_TAIL} art:border-transparent art:text-muted-foreground art:hover:text-foreground art:rounded-full`;
const HALO_SPRING = { type: "spring", stiffness: 700, damping: 35, mass: 1 } as const;
const RING_A: Transition = { layout: { ...HALO_SPRING, delay: 0.045 } };
const RING_B: Transition = { layout: { ...HALO_SPRING, delay: 0.09 } };
const RING_C: Transition = { layout: HALO_SPRING };
const expoOut = (t: number) => (t >= 1 ? 1 : 1 - Math.pow(2, -10 * t));
const PULSE: Transition = {
    opacity: { duration: 0.77, times: [0, 0.091, 1], ease: ["easeOut", ARTEMIS_EASE_OUT], delay: 0.25 },
    scale: { duration: 0.655, times: [0, 0.527, 1], ease: [expoOut, expoOut], delay: 0.25 },
};
const POP: Transition = { ...HALO_SPRING, delay: 0.12 };
const PANEL: Transition = { duration: 0.18, ease: ARTEMIS_EASE_OUT };
const CHECK_PATH = "M20 6 9 17l-5-5";
function Marker({ index, title, spot, active, reduce, onSelect, panelId }: {
    panelId: string;
    index: number;
    title: string;
    spot: { left: string; top: string };
    active: boolean;
    reduce: boolean;
    onSelect: () => void;
}) {
    return (<motion.button type="button" className={`${MARKER_BASE} ${active ? MARKER_ON : MARKER_OFF}`} aria-label={`Explore ${title}`} aria-pressed={active} aria-controls={panelId} tabIndex={reduce ? undefined : 0} style={{ left: spot.left, top: spot.top }} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onClick={onSelect}>
      {active ? (<span aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0">
          {reduce ? (<span className="art:absolute art:-inset-px art:rounded-full art:bg-primary art:ring-4 art:ring-primary/15"/>) : (<>
              <motion.span layoutId="fs3-hotspot-ring-a" className="art:absolute art:-inset-1 art:rounded-full art:bg-primary/10" initial={false} animate={{ opacity: 1 }} transition={RING_A}/>
              <motion.span layoutId="fs3-hotspot-ring-b" className="art:absolute art:-inset-1 art:rounded-full art:bg-primary/10" initial={false} animate={{ opacity: 1 }} transition={RING_B}/>
              <motion.span layoutId="fs3-hotspot-ring-c" className="art:absolute art:-inset-px art:rounded-full art:bg-primary art:ring-4 art:ring-primary/15" initial={false} animate={{ opacity: 1 }} transition={RING_C}/>
              <motion.span className="art:absolute art:-inset-1 art:rounded-full art:border art:border-primary/50" initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: [0, 0.65, 0], scale: [0.8, 1, 2.2] }} transition={PULSE}/>
            </>)}
        </span>) : null}
      <motion.span key={active ? "on" : "off"} aria-hidden="true" className="art:relative art:z-10 art:inline-block" initial={active && !reduce ? { opacity: 0, scale: 0.5, rotate: -35, y: 9 } : false} animate={{ opacity: 1, scale: 1, rotate: 0, y: 0 }} transition={POP}>
        {index + 1}
      </motion.span>
    </motion.button>);
}
function Check({ className }: {
    className: string;
}) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className} aria-hidden="true">
      <path d={CHECK_PATH}/>
    </svg>);
}
export default function FeatureSectionsProductHotspots({ content }: { content?: Partial<ArtemisFeatureContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const items: ArtemisFeatureItem[] = copy.items;
const artemisInstanceId = useArtemisInstanceId();
const PANEL_ID = `${artemisInstanceId}-R_9bsnpfdb_`;

    const [active, setActive] = useState(0);
    const prefersReduced = useReducedMotion() ?? false;
    const [hydrated, setHydrated] = useState(false);
    useEffect(() => setHydrated(true), []);
    const reduce = hydrated && prefersReduced;
    const f = items[active] ?? items[0];
    return (<>
      <section className="art:w-full art:bg-background art:px-6 art:py-12 art:text-foreground art:@min-[640px]/artemis:px-10 art:@min-[640px]/artemis:py-16">
        <div className="art:mx-auto art:max-w-6xl">
          <div className="art:mb-9 art:max-w-2xl">
            {copy.badge ? (<p className="art:mb-3 art:text-xs art:font-medium art:text-muted-foreground">
              {copy.badge}
            </p>) : null}
            <h2 className="art:text-balance art:text-4xl art:font-medium art:tracking-tight">
              {copy.headline}
              {copy.headlineAccent ? ` ${copy.headlineAccent}` : null}
            </h2>
            {copy.subhead ? (<p className="art:mt-4 art:max-w-xl art:text-sm art:leading-6 art:text-muted-foreground art:@min-[640px]/artemis:text-base">
              {copy.subhead}
            </p>) : null}
          </div>
          <div className="art:grid art:items-start art:gap-7 art:@min-[1024px]/artemis:grid-cols-[2fr_1fr] art:@min-[1024px]/artemis:gap-10">
            <div className="art:min-w-0">
              <div className="art:relative art:rounded-3xl art:p-3 art:@min-[640px]/artemis:p-5" style={{ background: "linear-gradient(130deg, rgba(159,211,208,.12), transparent 50%, rgba(233,198,153,.15))" }}>
                <div className="art:mb-3 art:flex art:items-center art:justify-between art:px-1 art:text-xs art:text-muted-foreground">
                  <span className="art:flex art:items-center art:gap-1.5" aria-hidden="true">
                    <span className="art:size-1.5 art:rounded-full art:bg-foreground/20"/>
                    <span className="art:size-1.5 art:rounded-full art:bg-foreground/20"/>
                    <span className="art:size-1.5 art:rounded-full art:bg-foreground/20"/>
                  </span>
                  <span>
                    {"Workspace tour"}
                  </span>
                  <span className="art:font-mono art:tabular-nums">
                    {pad(active + 1)}
                    {" /"}
                    {" "}
                    {pad(items.length)}
                  </span>
                </div>
                <div className="art:relative art:aspect-[16/10] art:rounded-2xl art:border art:border-border art:bg-background">
                  <WorkspaceArt />
                  {items.map((feature, i) => (<Marker panelId={PANEL_ID} key={feature.title} index={i} title={feature.title} spot={SPOTS[i % SPOTS.length]} active={i === active} reduce={reduce} onSelect={() => setActive(i)}/>))}
                </div>
              </div>
              <p className="art:mt-3 art:text-xs art:text-muted-foreground">
                <span className="art:hidden art:@min-[640px]/artemis:inline">
                  {"Click a marker or "}
                </span>
                <span className="art:@min-[640px]/artemis:lowercase">
                  {"Choose a feature"}
                </span>
                {" to explore the workspace."}
              </p>
            </div>
            <div className="art:min-w-0">
              <nav aria-label="Product features" className="art:space-y-2">
                {items.map((feature, i) => {
            const on = i === active;
            return (<motion.button key={feature.title} type="button" className={on ? ROW_ON : ROW_OFF} aria-pressed={on} aria-controls={PANEL_ID} tabIndex={reduce ? undefined : 0} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => setActive(i)}>
                      <span className="art:grid art:size-7 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:font-mono art:text-xs art:tabular-nums">
                        {pad(i + 1)}
                      </span>
                      <span className="art:flex-1">
                        {feature.title}
                      </span>
                      {on ? <Check className="art:lucide art:lucide-check art:size-4"/> : null}
                    </motion.button>);
        })}
              </nav>
              <div id={PANEL_ID} aria-live="polite" aria-atomic="true" className="art:mt-7 art:min-h-56 art:px-1">
                <AnimatePresence mode="wait" initial={false}>
                  {f ? (<motion.div key={active} initial={reduce ? false : { opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} exit={reduce ? undefined : { opacity: 0, y: -4 }} transition={reduce ? { duration: 0 } : PANEL}>
                    <h3 className="art:text-xl art:font-medium art:tracking-tight">
                      {f.title}
                    </h3>
                    <p className="art:mt-3 art:text-sm art:leading-6 art:text-muted-foreground">
                      {f.description}
                    </p>
                    {f.bullets?.length ? (<ul className="art:mt-5 art:space-y-3">
                      {f.bullets.map((b) => (<li key={b} className="art:flex art:gap-2 art:text-xs art:leading-5 art:text-muted-foreground">
                          <Check className="art:lucide art:lucide-check art:mt-0.5 art:size-3.5 art:shrink-0"/>
                          {b}
                        </li>))}
                    </ul>) : null}
                  </motion.div>) : null}
                </AnimatePresence>
              </div>
            </div>
          </div>
        </div>
      </section>
    </>);
}
